"use client";

import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadGeistMono } from "@remotion/google-fonts/GeistMono";
import type React from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import {
  type ResolvedElement,
  type Timing,
  useTimeline,
} from "@/lib/remocn/timeline";
import {
  CARD_END,
  DEFAULT_AFTER,
  DEFAULT_BEFORE,
  DEFAULT_VALUE,
  type GlowBornCardElementId,
  glowBornCardTimeline,
} from "./timeline";

const geist = loadGeist("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});
const mono = loadGeistMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

const ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const LIGHT = Easing.bezier(0.22, 1, 0.36, 1);
const MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const EXIT = Easing.bezier(0.55, 0, 1, 0.45);
const SWAY = Easing.bezier(0.45, 0, 0.55, 1);
const MORPH = { damping: 200 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };

export const GLOW_BORN_CARD_DURATION = CARD_END;

const ramp = (f: number, start: number, dur: number, easing = ENTER) =>
  interpolate(f, [start, start + dur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing,
  });

const mix = (a: number, b: number, t: number) => a + (b - a) * t;

export interface GlowBornCardProps {
  theme?: "dark" | "light";
  accent?: string;
  primary?: string;
  before?: string;
  after?: string;
  title?: string;
  label?: string;
  value?: string;
  hint?: string;
  branch?: string;
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /** Primary button label before the press. */
  actionLabel?: string;
  /** Primary button label once the import is done. */
  doneLabel?: string;
  /** Secondary button label. */
  cancelLabel?: string;
  /** Text color of the headline; overrides the theme ink. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the headline and card. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Size of the headline and card, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  /**
   * Moves, trims or stretches the headline, the glow, the card's beats and
   * the camera, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<GlowBornCardElementId>;
}

const LIGHT_GROUND: Partial<GradientParams> = {
  colors: ["#9fd8ff", "#3f7dff", "#1c3bb0", "#8ff0e0"],
  background: "#eef1f6",
};

function Words({
  text,
  frame,
  el,
  size,
  color,
}: {
  text: string;
  frame: number;
  el: ResolvedElement<GlowBornCardElementId>;
  size: number;
  color: string;
}) {
  const words = text.split(" ");
  return (
    <div style={{ display: "flex", whiteSpace: "nowrap" }}>
      {words.map((w, i) => {
        const p = ramp(
          frame,
          el.start + i * el.beat("stagger"),
          el.beat("word"),
        );
        return (
          <span
            key={`${w}-${i.toString()}`}
            style={{
              display: "inline-block",
              overflow: "hidden",
              paddingBottom: size * 0.12,
              marginBottom: -size * 0.12,
              marginRight: i < words.length - 1 ? size * 0.26 : 0,
            }}
          >
            <span
              style={{
                display: "inline-block",
                transform: `translateY(${mix(105, 0, p)}%)`,
                filter: p < 1 ? `blur(${(1 - p) * 6}px)` : undefined,
                color,
              }}
            >
              {w}
            </span>
          </span>
        );
      })}
    </div>
  );
}

function RepoIcon({ size, color }: { size: number; color: string }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} aria-hidden>
      <g
        fill="none"
        stroke={color}
        strokeWidth={1.5}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <circle cx={6.5} cy={5.5} r={2} />
        <circle cx={6.5} cy={18.5} r={2} />
        <circle cx={17.5} cy={8.5} r={2} />
        <path d="M6.5 7.5v9M17.5 10.5c0 3.5-4 3-8.6 6.2" />
      </g>
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function GlowBornCard(props: GlowBornCardProps) {
  const {
    theme = "dark",
    accent = "#45f0d6",
    primary = "#3B5BFD",
    before = DEFAULT_BEFORE,
    after = DEFAULT_AFTER,
    title = "Import from repository",
    label = "Repository",
    value = DEFAULT_VALUE,
    hint = "Public or private, any branch",
    branch = "main · 214 commits · 3h ago",
    ground,
    groundParams,
    actionLabel = "Import",
    doneLabel = "Imported",
    cancelLabel = "Cancel",
    ink: inkProp,
    background,
    fontFamily = geist.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    glowBornCardTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const partEl = tl.get("part");
  const pushEl = tl.get("push");
  const glow = tl.get("glow");
  const recedeEl = tl.get("recede");
  const typing = tl.get("typing");
  const pressEl = tl.get("press");
  const doneEl = tl.get("done");
  const dark = theme === "dark";
  const portrait = height > width * 1.2;
  const stageW = portrait ? 1080 : 1280;
  const stageH = portrait ? 1920 : 720;
  const sc = width / stageW;
  const u = portrait ? 2.1 : 1.12;

  const ink = inkProp ?? (dark ? "#f3f6ff" : "#10131c");
  const cardInk = dark ? "#eef1f8" : "#141822";
  const muted = dark ? "rgba(226,232,248,0.52)" : "rgba(20,24,34,0.5)";
  const hair = dark ? "rgba(255,255,255,0.1)" : "rgba(20,24,48,0.1)";
  const fieldBg = dark ? "rgba(255,255,255,0.035)" : "#f7f8fa";
  const surface = dark ? "#12151c" : "#ffffff";
  const footerBg = dark ? "rgba(255,255,255,0.025)" : "#f9fafb";

  const cardW = (portrait ? 420 : 380) * u;
  const cardH = 236 * u;
  const pad = 20 * u;
  const fontSize = portrait ? 80 : 42;
  const margin = portrait ? 34 : 22;

  const part = spring({
    frame: frame - partEl.start,
    fps,
    config: MORPH,
    durationInFrames: partEl.length,
  });
  const gap = mix(
    portrait ? 0 : fontSize * 0.26,
    (portrait ? cardH : cardW) + margin * 2,
    part,
  );

  const ignite = ramp(frame, glow.start, glow.beat("ignite"), LIGHT);
  const fill = ramp(
    frame,
    glow.start + glow.beat("fillAt"),
    glow.beat("fill"),
    LIGHT,
  );
  const recede = ramp(frame, recedeEl.start, recedeEl.length, MOVE);
  const glowFade =
    1 -
    ramp(
      frame,
      recedeEl.start + recedeEl.beat("fadeAt"),
      recedeEl.beat("fade"),
      EXIT,
    );
  const cardOn = ramp(
    frame,
    glow.start + glow.beat("cardAt"),
    glow.beat("card"),
  );
  const halo =
    ramp(
      frame,
      recedeEl.start + recedeEl.beat("haloAt"),
      recedeEl.beat("halo"),
      LIGHT,
    ) *
    (1 -
      ramp(
        frame,
        recedeEl.start + recedeEl.beat("haloOutAt"),
        recedeEl.beat("haloOut"),
        EXIT,
      ));

  const blobW =
    mix(36 * u, mix(cardW * 0.4, cardW * 1.04, fill), ignite) *
    (1 - 0.55 * recede);
  const blobX = cardW * 0.3 * recede;
  const blobH = mix(36 * u, mix(cardH * 0.6, cardH * 1.04, fill), ignite);
  const blobR = mix(blobW / 2, 18 * u, fill);
  const blobBlur = mix(26, 10, fill) * u;
  const edge = mix(4, 120, recede);

  const typed = Math.round(
    interpolate(frame, [typing.start, typing.end], [0, value.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }),
  );
  const shown = value.slice(0, typed);
  const caret =
    frame >= recedeEl.start + recedeEl.beat("caretAt") &&
    frame < pressEl.start &&
    (typed < value.length || Math.floor(frame / 8) % 2 === 0);
  const focus =
    ramp(frame, typing.start + typing.beat("focusAt"), typing.beat("focus")) *
    (1 -
      ramp(
        frame,
        pressEl.start + pressEl.beat("blurAt"),
        pressEl.beat("blur"),
        EXIT,
      ));
  const press = Math.max(
    0,
    spring({ frame: frame - pressEl.start, fps, config: CHIP }) -
      spring({
        frame: frame - pressEl.start - pressEl.beat("release"),
        fps,
        config: CHIP,
      }),
  );
  const done = spring({ frame: frame - doneEl.start, fps, config: CHIP });
  const doneIn = ramp(frame, doneEl.start, doneEl.length);
  const metaIn = ramp(
    frame,
    typing.end + typing.beat("metaGap"),
    typing.beat("meta"),
    LIGHT,
  );

  const landAt = pushEl.start + pushEl.beat("land");
  const pushAt = (f: number) =>
    1 +
    (portrait ? 0.05 : 0.03) *
      ramp(f, pushEl.start, pushEl.beat("land"), SWAY) +
    0.02 * ramp(f, landAt, pushEl.length - pushEl.beat("land"), SWAY);
  const push = pushAt(frame);
  // Two in-out pushes meet at the push's `land`, so "moving" is read off the step
  // against either neighbouring frame, weighed at the stage's edge.
  const pushing =
    Math.abs(pushAt(frame + speed) - push) * stageW * 0.5 > 1e-3 ||
    Math.abs(push - pushAt(frame - speed)) * stageW * 0.5 > 1e-3;
  const settleEl = tl.get("settle");
  const settle = ramp(frame, settleEl.start, settleEl.length, MOVE);
  const tilt = mix(8, 0, settle);

  const resolvedGround: GshPresetId =
    ground ?? (dark ? "film-blue" : "glasswork");
  const resolvedParams = groundParams ?? (dark ? undefined : LIGHT_GROUND);

  const glowCore = dark ? "rgba(255,255,255,0.96)" : "rgba(255,255,255,1)";

  const card = (
    <div
      style={{
        position: "absolute",
        left: "50%",
        top: "50%",
        width: cardW,
        height: cardH,
        marginLeft: -cardW / 2,
        marginTop: -cardH / 2,
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 18 * u,
          opacity: halo * 0.8,
          boxShadow: `0 0 ${26 * u}px ${4 * u}px color-mix(in oklab, ${accent} ${dark ? 60 : 45}%, transparent), 0 0 ${80 * u}px ${22 * u}px color-mix(in oklab, ${accent} ${dark ? 26 : 20}%, transparent)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 16 * u,
          background: surface,
          boxShadow: dark
            ? "0 0 0 1px rgba(255,255,255,0.09), inset 0 1px 0 rgba(255,255,255,0.05), 0 24px 56px rgba(2,6,24,0.55)"
            : "0 0 0 1px rgba(20,24,48,0.07), 0 1px 2px rgba(20,30,90,0.06), 0 22px 50px rgba(20,30,90,0.14)",
          opacity: cardOn,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          fontFamily,
          letterSpacing: "-0.005em",
          lineHeight: 1.3,
        }}
      >
        <div style={{ padding: `${pad}px ${pad}px 0` }}>
          <div style={{ fontSize: 20 * u, color: cardInk }}>{title}</div>
          <div style={{ fontSize: 15 * u, color: muted, marginTop: 16 * u }}>
            {label}
          </div>
          <div
            style={{
              marginTop: 8 * u,
              height: 42 * u,
              borderRadius: 8 * u,
              border: `1px solid ${focus > 0 ? `color-mix(in oklab, ${primary} ${Math.round(focus * 75)}%, ${hair})` : hair}`,
              boxShadow: `0 0 0 ${3 * u * focus}px color-mix(in oklab, ${primary} ${Math.round(focus * 22)}%, transparent)`,
              background: fieldBg,
              display: "flex",
              alignItems: "center",
              gap: 10 * u,
              padding: `0 ${12 * u}px`,
              fontFamily: mono.fontFamily,
              fontSize: 15 * u,
              letterSpacing: 0,
              color: typed > 0 ? cardInk : muted,
            }}
          >
            <div style={{ order: -2, display: "flex" }}>
              <RepoIcon size={18 * u} color={muted} />
            </div>
            {typed > 0 ? shown : "owner/name"}
            <span
              style={{
                display: "inline-block",
                width: 2 * u,
                height: 20 * u,
                margin: typed > 0 ? `0 0 0 ${-8 * u}px` : `0 ${-8 * u}px 0 0`,
                order: typed > 0 ? 1 : -1,
                background: primary,
                opacity: caret ? 1 : 0,
              }}
            />
          </div>
          <div
            style={{
              position: "relative",
              marginTop: 8 * u,
              height: 18 * u,
              fontSize: 14 * u,
              color: muted,
              fontVariantNumeric: "tabular-nums",
            }}
          >
            <div
              style={{ position: "absolute", inset: 0, opacity: 1 - metaIn }}
            >
              {hint}
            </div>
            <div
              style={{
                position: "absolute",
                inset: 0,
                opacity: metaIn,
                transform: `translateY(${(1 - metaIn) * 4 * u}px)`,
              }}
            >
              {branch}
            </div>
          </div>
        </div>
        <div
          style={{
            marginTop: "auto",
            display: "flex",
            justifyContent: "flex-end",
            alignItems: "center",
            gap: 10 * u,
            fontSize: 16 * u,
            padding: `${11 * u}px ${pad}px`,
            borderTop: `1px solid ${hair}`,
            background: footerBg,
          }}
        >
          <div
            style={{
              padding: `${7 * u}px ${14 * u}px`,
              borderRadius: 9 * u,
              border: `1px solid ${hair}`,
              color: cardInk,
            }}
          >
            {cancelLabel}
          </div>
          <div
            style={{
              position: "relative",
              padding: `${7 * u}px ${16 * u}px`,
              borderRadius: 9 * u,
              background: primary,
              color: "#fff",
              transform: `scale(${1 - 0.06 * press})`,
              boxShadow: `inset 0 1px 0 rgba(255,255,255,0.22), 0 1px 2px rgba(4,8,30,${dark ? 0.4 : 0.18})`,
              display: "flex",
              alignItems: "center",
              gap: 7 * u,
            }}
          >
            <div
              style={{
                width: 16 * u * doneIn,
                height: 16 * u,
                overflow: "hidden",
                display: "flex",
                alignItems: "center",
                transform: `scale(${done})`,
              }}
            >
              <svg
                viewBox="0 0 24 24"
                width={16 * u}
                height={16 * u}
                aria-hidden
              >
                <path
                  d="m5 12.5 4.5 4.5L19 7.5"
                  fill="none"
                  stroke="#fff"
                  strokeWidth={2.4}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeDasharray={22}
                  strokeDashoffset={
                    22 *
                    (1 -
                      ramp(
                        frame,
                        doneEl.start + doneEl.beat("checkAt"),
                        doneEl.beat("check"),
                      ))
                  }
                />
              </svg>
            </div>
            {doneIn > 0.5 ? doneLabel : actionLabel}
          </div>
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: 0,
          height: 0,
          opacity: ignite * glowFade,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: -cardW * 0.7,
            top: -cardH * 0.9,
            width: cardW * 1.4,
            height: cardH * 1.8,
            maskImage: `linear-gradient(90deg, transparent ${edge - 10}%, black ${edge + 34}%)`,
            WebkitMaskImage: `linear-gradient(90deg, transparent ${edge - 10}%, black ${edge + 34}%)`,
          }}
        >
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              width: blobW * 1.25,
              height: blobH * 1.35,
              marginLeft: (-blobW * 1.25) / 2 + blobX,
              marginTop: (-blobH * 1.35) / 2,
              borderRadius: blobR * 1.4,
              background: accent,
              filter: `blur(${blobBlur * 1.8}px)`,
              opacity: 0.85,
            }}
          />
          <div
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              width: blobW,
              height: blobH,
              marginLeft: -blobW / 2 + blobX,
              marginTop: -blobH / 2,
              borderRadius: blobR,
              background: `radial-gradient(70% 70% at 50% 50%, ${glowCore} 0%, color-mix(in oklab, ${accent} 55%, white) 55%, ${accent} 100%)`,
              filter: `blur(${blobBlur}px)`,
            }}
          />
        </div>
      </div>
    </div>
  );

  return (
    <AbsoluteFill style={{ fontFamily, overflow: "hidden" }}>
      {background === undefined ? (
        <>
          <GshGround
            preset={resolvedGround}
            params={resolvedParams}
            timeOffset={4}
            timeScale={0.5}
          />
          <AbsoluteFill
            style={{
              background: dark
                ? "radial-gradient(60% 50% at 50% 50%, rgba(3,7,18,0.35) 0%, rgba(3,7,18,0) 100%)"
                : "radial-gradient(60% 50% at 50% 50%, rgba(255,255,255,0.4) 0%, rgba(255,255,255,0) 100%)",
            }}
          />
        </>
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: stageW,
            height: stageH,
            transform: `scale(${sc})`,
            transformOrigin: "0 0",
            perspective: 1800,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              flexDirection: portrait ? "column" : "row",
              alignItems: "center",
              justifyContent: "center",
              fontSize,
              fontWeight: 400,
              letterSpacing: "-0.03em",
              lineHeight: 1.1,
              transform: `scale(${push}) rotateX(${portrait ? tilt : 0}deg) rotateY(${portrait ? 0 : -tilt}deg)${glide(pushing)}`,
              transformOrigin: "50% 50%",
            }}
          >
            <Words
              text={before}
              frame={frame}
              el={tl.get("before")}
              size={fontSize}
              color={ink}
            />
            <div
              style={{
                position: "relative",
                width: portrait ? 0 : gap,
                height: portrait ? gap : 0,
                flexShrink: 0,
              }}
            >
              {frame >= glow.start ? card : null}
            </div>
            <Words
              text={after}
              frame={frame}
              el={tl.get("after")}
              size={fontSize}
              color={ink}
            />
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

export default GlowBornCard;

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The headline rises word by word and parts; a glow ignites in the gap,
// fills out into a card and recedes off it; the repository types into the
// field, the button is pressed and turns to done while the camera pushes in.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. The ids
// are public: a saved `timing` prop refers to them.

export type GlowBornCardElementId =
  | "before"
  | "settle"
  | "after"
  | "part"
  | "push"
  | "glow"
  | "recede"
  | "typing"
  | "press"
  | "done";

export interface GlowBornCardTimingProps {
  before?: string;
  after?: string;
  value?: string;
}

export const DEFAULT_BEFORE = "Or import a scene from";
export const DEFAULT_AFTER = "your repo";
export const DEFAULT_VALUE = "lumen-labs/launch";

const B = {
  words: -8,
  part: 18,
  ignite: 20,
  fill: 26,
  card: 32,
  recede: 34,
  recedeLen: 16,
  type: 60,
  press: 90,
  done: 96,
  end: 136,
};

/** Frames the demo runs, to the end of the camera's last push. */
export const CARD_END = B.end;

const WORD_STAGGER = 2;
const WORD = 14;
/** Typing pace: frames per character. */
const PER_CHAR = 1.5;

const wordsOf = (text: string) => text.split(" ");

// A headline half rises a word every `stagger` frames, each over `word`. The
// camera push runs from the part to the end, landing its first push at
// `land`. The glow ignites, fills and shows the card from its start; the
// recede fades the glow and the halo and lets the caret in. Typing runs one
// character every 1.5 frames, the field focusing `focusAt` before it and the
// meta line following `metaGap` after it.
export const glowBornCardTimeline = defineTimeline<
  GlowBornCardElementId,
  GlowBornCardTimingProps
>(
  ({
    before = DEFAULT_BEFORE,
    after = DEFAULT_AFTER,
    value = DEFAULT_VALUE,
  }): TimelineElement<GlowBornCardElementId>[] => [
    {
      id: "before",
      lane: "Headline",
      label: before,
      start: B.words,
      length: (wordsOf(before).length - 1) * WORD_STAGGER + WORD,
      beats: { stagger: WORD_STAGGER, word: WORD },
    },
    {
      id: "settle",
      lane: "Camera",
      label: "settle",
      start: -6,
      length: 30,
    },
    {
      id: "after",
      lane: "Headline",
      label: after,
      start: B.words + 10,
      length: (wordsOf(after).length - 1) * WORD_STAGGER + WORD,
      follows: "before",
      beats: { stagger: WORD_STAGGER, word: WORD },
    },
    {
      id: "part",
      lane: "Headline",
      label: "part",
      start: B.part,
      length: 18,
    },
    {
      id: "push",
      lane: "Camera",
      label: "push",
      start: B.part,
      length: B.end - B.part,
